dtsPropsFor.Button:
/** "primary" = Teal-CTA (Verlauf blendet bei Hover ein), "secondary" = Glass-Pill, "gradient" = permanenter Logo-Verlauf (der EINE Hero-CTA). Default: "primary". */
variant?: "primary" | "secondary" | "gradient";
/** Nur für secondary relevant: "light" stylt die Glass-Pille für helle Gründe (theme-light). Default: "dark". */
tone?: "dark" | "light";
children?: React.ReactNode;
className?: string;
disabled?: boolean;
type?: "button" | "submit" | "reset";
onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.LogoLockup:
/** Höhe über Utility-Klasse steuern: Nav h-11, Footer h-8 (immer mit w-auto). Nur auf dunklem Grund einsetzen. */
className?: string;
/** Bild-Ladepriorität (fetchPriority=high), für Above-the-fold-Einbau. */
priority?: boolean;

dtsPropsFor.LogoMark:
/** Kantenlänge in px (üblich 40 oder 64). */
size?: number;
className?: string;

dtsPropsFor.MetricCard:
/** KPI-Beschriftung, wird uppercase gesetzt (z. B. "Auslastung"). */
label: string;
/** Anzeigewert als String (z. B. "62 %", "48,2 kWh"). */
value: string;
/** Optionaler Mini-Balken, Füllstand 0–1. */
bar?: number;
/** Optionale Zeile unter dem Wert (z. B. Trend "+12 % ggü. Vortag"). */
sub?: string;
/** Akzentfarbe des Balkens, CSS-Farbe/Var (Default var(--color-brand-teal)). */
accent?: string;
/** "dark" = Glass-Chip auf dunklem Panel (Default), "light" = heller App-Ground. */
tone?: "dark" | "light";
